import { defineConfig } from "drizzle-kit";

// Tables defined in src/schema are generated by drizzle-kit. Roles, RLS policies, triggers, and
// partitioned tables live in custom SQL migrations in the same folder (research R4, R11).
export default defineConfig({
  dialect: "postgresql",
  schema: "./src/schema/*.ts",
  out: "./migrations",
  dbCredentials: {
    url: process.env.DATABASE_URL ?? "postgres://guidesk:guidesk_local_only@localhost:5432/guidesk",
  },
  strict: true,
  verbose: true,
});
